// Ported from the Node app's Sequelize model GradeBand (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class GradeBandConfiguration : IEntityTypeConfiguration<GradeBand>
{
    public void Configure(EntityTypeBuilder<GradeBand> builder)
    {
        builder.ToTable("grade_bands");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Board).HasColumnName("board").HasColumnType("nvarchar(20)").HasMaxLength(20).IsRequired().HasDefaultValueSql("N'CBSE'");
        builder.Property(e => e.Grade).HasColumnName("grade").HasColumnType("nvarchar(10)").HasMaxLength(10).IsRequired();
        builder.Property(e => e.MinPercent).HasColumnName("min_percent").HasColumnType("decimal(5,2)");
    }
}
